require "rails_helper"

RSpec.describe "Internal::V1::Timekeeping::EntrySnapshots", type: :request do
  let(:snapshot_company) { create(:company) }
  let(:snapshot_project) { create(:project, client: create(:client, company: snapshot_company)) }
  let(:snapshot_user) { create(:user).tap { |user| create(:employment, company: snapshot_company, user:) } }

  def snapshot_body(version:)
    entry = TimekeepingContract.load(:entry_snapshots).fetch("entry_fields").index_with(nil).merge(
      "id" => 90_101, "company_id" => snapshot_company.id, "version" => version, "project_id" => snapshot_project.id,
      "user_id" => snapshot_user.id, "work_date" => "2026-03-02", "duration" => 90.0, "note" => "v#{version}",
      "bill_status" => "unbilled", "review_status" => "not_required", "locked" => false, "source" => "manual",
      "source_metadata" => {}, "proof_metadata" => {}, "created_at" => "2026-03-02T09:00:00Z",
      "updated_at" => "2026-03-02T09:00:00Z"
    )
    { "schema_version" => 1, "snapshots" => [{ "generation" => 1, "outbox_position" => version, "entry" => entry }] }
  end

  def post_snapshots(token, version:)
    headers = { "Content-Type" => "application/json", "Idempotency-Key" => SecureRandom.uuid }
    headers["Authorization"] = "Bearer #{token}" if token
    post "/internal/v1/timekeeping/entry-snapshots", params: snapshot_body(version:).to_json, headers:
  end

  it "refuses a user token with 401 and leaves the seeded row unchanged" do
    with_timekeeping_service_token do |service_token|
      post_snapshots(service_token, version: 1)
      expect(response).to have_http_status(:ok)
    end
    before = TimesheetEntry.find(90_101).attributes
    expect([before["version"], before["note"]]).to eq([1, "v1"])
    user_token = Timekeeping::UserToken.mint(user: snapshot_user, company: snapshot_company, private_key: timekeeping_key_pair)

    # "A request with no credential, a wrong one or a user token gets 401 or 403 and writes nothing."
    with_timekeeping_service_token do
      post_snapshots(user_token, version: 2)
    end

    expect(response).to have_http_status(:unauthorized)
    expect(response.parsed_body).to eq("reason" => "unauthorized")
    expect(TimesheetEntry.find(90_101).attributes).to eq(before)
  end
end

RSpec.describe "Internal::V1::Timekeeping::EntrySnapshots version upsert", type: :request do
  it "applies v2, ignores a later v1 and a repeated v2, and keeps v2's stored data" do
    company = create(:company)
    project = create(:project, client: create(:client, company:))
    user = create(:user)
    create(:employment, company:, user:)
    entry_id = 90_101
    snapshot = lambda do |version|
      entry = TimekeepingContract.load(:entry_snapshots).fetch("entry_fields").index_with(nil).merge(
        "id" => entry_id, "company_id" => company.id, "version" => version, "project_id" => project.id,
        "user_id" => user.id, "work_date" => "2026-03-02", "duration" => 90.0, "note" => "v#{version}",
        "bill_status" => "unbilled", "review_status" => "not_required", "locked" => false, "source" => "manual",
        "source_metadata" => {}, "proof_metadata" => {}, "created_at" => "2026-03-02T09:00:00Z",
        "updated_at" => "2026-03-02T09:00:00Z"
      )
      { "schema_version" => 1,
        "snapshots" => [{ "generation" => TimekeepingOwnership.current.generation, "outbox_position" => version, "entry" => entry }] }
    end

    with_timekeeping_service_token do |token|
      deliver = lambda do |version|
        post "/internal/v1/timekeeping/entry-snapshots", params: snapshot.call(version).to_json,
          headers: { "Authorization" => "Bearer #{token}", "Content-Type" => "application/json",
                     "Idempotency-Key" => SecureRandom.uuid }
        response.parsed_body
      end

      # "It upserts by entry `id` and applies a snapshot only when its `version` is higher than the row's."
      expect(deliver.call(2)).to eq("applied" => 1, "ignored" => 0)
      expect(deliver.call(1)).to eq("applied" => 0, "ignored" => 1)
      expect(TimesheetEntry.find(entry_id).attributes.slice("version", "note")).to eq("version" => 2, "note" => "v2")
      expect(deliver.call(2)).to eq("applied" => 0, "ignored" => 1)
      expect(TimesheetEntry.where(id: entry_id).count).to eq(1)
      expect(TimesheetEntry.find(entry_id).attributes.slice("version", "note")).to eq("version" => 2, "note" => "v2")
    end
  end
end

RSpec.describe "Internal::V1::Timekeeping::EntrySnapshots idempotency", type: :request do
  it "returns the first answer for a replayed key and batch and answers idempotency_key_reused for a new batch under that key" do
    company = create(:company)
    project = create(:project, client: create(:client, company:))
    user = create(:user)
    create(:employment, company:, user:)
    entry_id = 90_201
    batch = lambda do |version|
      entry = TimekeepingContract.load(:entry_snapshots).fetch("entry_fields").index_with(nil).merge(
        "id" => entry_id, "company_id" => company.id, "version" => version, "project_id" => project.id,
        "user_id" => user.id, "work_date" => "2026-03-02", "duration" => 90.0, "note" => "v#{version}",
        "bill_status" => "unbilled", "review_status" => "not_required", "locked" => false, "source" => "manual",
        "source_metadata" => {}, "proof_metadata" => {}, "created_at" => "2026-03-02T09:00:00Z",
        "updated_at" => "2026-03-02T09:00:00Z"
      )
      { "schema_version" => 1,
        "snapshots" => [{ "generation" => TimekeepingOwnership.current.generation, "outbox_position" => version, "entry" => entry }] }
    end
    key = SecureRandom.uuid

    with_timekeeping_service_token do |token|
      deliver = lambda do |version|
        post "/internal/v1/timekeeping/entry-snapshots", params: batch.call(version).to_json,
          headers: { "Authorization" => "Bearer #{token}", "Content-Type" => "application/json", "Idempotency-Key" => key }
        [response.status, response.parsed_body]
      end

      # contracts/timekeeping/idempotency.yml: "Same key and body returns the same answer; same key with a new body
      # answers idempotency_key_reused".
      first = deliver.call(1)
      expect(first).to eq([200, { "applied" => 1, "ignored" => 0 }])
      expect(deliver.call(1)).to eq(first)

      expect(deliver.call(2)).to eq([422, { "reason" => "idempotency_key_reused" }])
      expect(TimesheetEntry.find(entry_id).attributes.slice("version", "note")).to eq("version" => 1, "note" => "v1")
    end
  end
end
